const d = $input.first().json;
const app = 'https://app.simple-solution.co.il';
const nis = (n) => Math.round(n || 0).toLocaleString('he-IL') + ' ₪';
const L = [];
L.push(`לידים חדשים ב-24 שעות: ${d.new_leads.length}`);
d.new_leads.forEach(l => L.push(`  · ${l.name}${l.biz ? ' · ' + l.biz : ''} (${l.source})`));
if (d.leads_no_touch) L.push(`לידים חדשים שעוד לא נוצר איתם קשר: ${d.leads_no_touch}`);
if (d.next_steps_due.length) { L.push('', 'צעדים להיום:'); d.next_steps_due.forEach(s => L.push(`  · ${s.name}: ${s.step || 'צעד הבא'}`)); }
if (d.tasks_due.length) { L.push('', 'משימות להיום ובאיחור:'); d.tasks_due.forEach(t => L.push(`  · ${t.title} (${t.due})`)); }
if (d.quotes_waiting.length) { L.push('', 'הצעות שמחכות לתשובה:'); d.quotes_waiting.forEach(q => L.push(`  · ${q.no} · ${q.status} · ${q.views} צפיות`)); }
if (d.payments_overdue.length) { L.push('', 'תשלומים באיחור:'); d.payments_overdue.forEach(p => L.push(`  · ${p.client}: ${p.what} · ${nis(p.amount)} · ${p.due}`)); }
L.push('', app);
return [{ json: { subject: 'simple-CRM · סיכום בוקר', text: L.join('\n') } }];
